import java.util.Scanner;

public class Main {
    static int n, k, p;
    static int[][] memo;
    static int[] fact, invFact;

    static int power(int base, int exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * cur) % p;
            }
            cur = (cur * cur) % p;
            exp >>= 1;
        }
        return (int) res;
    }

    static int lowbit(int x) {
        return x & (-x);
    }

    static void prepare() {
        fact = new int[n + 1];
        invFact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % p);
        }
        invFact[n] = power(fact[n], p - 2);
        for (int i = n; i >= 1; i--) {
            invFact[i - 1] = (int) ((long) invFact[i] * i % p);
        }
    }

    static int solve(int index, int mask) {
        if (memo[index][mask] != -1)
            return memo[index][mask];
        if (mask == 0) {
            int res = fact[n];
            for (int i = 1; i <= index; i++)
                res = (int) ((long) res * (k - i + 1) % p);
            return memo[index][mask] = res;
        }
        int total = 0;
        int remaining = mask - lowbit(mask);
        for (int subset = remaining; subset != 0; subset = (subset - 1) & remaining) {
            total = (total + (int) ((long) invFact[mask - subset] * solve(index + 1, subset) % p)) % p;
        }
        total = (total + (int) ((long) invFact[mask] * solve(index + 1, 0) % p)) % p;
        return memo[index][mask] = total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        p = sc.nextInt();
        int result = 1;
        for (int i = 1; i <= n; i++) {
            result = (int) ((long) result * k % p);
        }
        if (n % 2 == 0) {
            memo = new int[n + 1][1 << n];
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j < (1 << n); j++) {
                    memo[i][j] = -1;
                }
            }
            prepare();
            result = (result - solve(0, n) + p) % p;
        }
        System.out.println(result);
        sc.close();
    }
}
